import{_ as t,c as n,j as e,a as l,o as r}from"./chunks/framework.CqbvlPrP.js";const u=JSON.parse('{"title":"第一百六十四章 屎粪中的蛆虫","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/164第一百六十四章 屎粪中的蛆虫.md","filePath":"meditation/巴利文大藏经/164第一百六十四章 屎粪中的蛆虫.md"}'),o={name:"meditation/巴利文大藏经/164第一百六十四章 屎粪中的蛆虫.md"};function _(s,a,i,d,p,c){return r(),n("div",null,a[0]||(a[0]=[e("h1",{id:"第一百六十四章-屎粪中的蛆虫",tabindex:"-1"},[l("第一百六十四章 屎粪中的蛆虫 "),e("a",{class:"header-anchor",href:"#第一百六十四章-屎粪中的蛆虫","aria-label":'Permalink to "第一百六十四章 屎粪中的蛆虫"'},"​")],-1),e("p",null,"完全读懂巴利文大藏经",-1),e("p",null,"相应部17相应5经/粪虫经(利得恭敬相应/因缘篇/如来记说)",-1),e("p",null,"有个时候，佛陀住在舍卫城的祇树林给孤独园，有一天，佛陀对出家弟子们说：“弟子们，世间人丰厚的供养，富贵舒适的生活，世间人虔诚的尊敬、恭敬，家喻户晓的名誉声望，这些是让人内心颤抖恐怖的，这些是让人内心激烈搅动的，这些是让人内心暴躁不安的，这些是修行人内心达到清净安稳的障碍，这些是修行人内心挣脱束缚捆绑的阻碍。",-1),e("p",null,"弟子们，就如同一只满身是屎粪的蛆虫，它以屎粪为食物，有一天它找到了一大堆屎粪，于是它就轻蔑、鄙视的对其他蛆虫说：“怎么样！我现在拥有这么大一堆屎粪，我已经尽情的享用了这些美食，你们那个能够跟我相比！”同样的道理，弟子们，有个家喻户晓很出名，并且受到世间人尊敬、恭敬的出家人，他中午的时候穿上法衣，拿着饭钵到乡村或是城镇中化缘饭食，他来到一户富贵的人家，这家人盛情的款待他，拿出家中最好的饮食来供养他，这个出家人也敞开肚皮尽情的享用美食，他吃的弯腰捧腹，直打饱嗝，连走路都快迈不开脚步了。这户富贵人家还邀请这个出家人明天继续到他们家里面来接受美食的供养。于是，这个出家人就慢悠悠的回到僧团中，并对僧团中其他的出家人夸耀到：“我今天接受了一户富贵人家的供养，我尽情的享用了美妙的饮食，吃的我肚子都快撑爆了，这家人还邀请我明天继续到他们家去接受美食的供养，你们看这家人还供养给了我漂亮的衣服，崭新的床被，各种日常用品，治病用的药物，还给我打包了很多好吃的食物，他们还将一间空房供养给我居住，你们看我给他们种植的福田有多大！你们看看我修行的境界有多高！他们对我如此的尊重、恭敬，他们供养给我这么多的物品。你们再看看你们自己，你们这些人毫无修行可言，世间人都不怎么相信你们，世间人都不怎么供养你们，你们也得不到世间人美妙饮食，漂亮衣服，崭新床被，各种日常用品，治病用的药物的供养，你们得到的不过是些粗劣、不值钱的东西。你们看看我，我的修行境界多高。世间人供养给我的物品多丰厚，你们能够跟我相比吗！你们能够跟我相提并论吗！”弟子们，这个出家人他自己获得丰厚的供养，获得世间人虔诚的尊敬、恭敬，获得家喻户晓的名誉声望后，就轻蔑、瞧不起僧团中其他的出家人，他就如同那个获得一堆屎粪后就向其他蛆虫夸耀、炫耀自己的蛆虫一样，他将会被丰厚的供养，世间人虔诚的尊敬、恭敬，家喻户晓的名誉声望束缚捆绑，他将会沉浸、沉溺在欲望的海洋中不得解脱，他清净的境界将会退失，他将会产生无数的烦恼和痛苦，这些丰厚的供养，世间人虔诚的尊敬、恭敬，家喻户晓的名誉声望只会给他带来不幸和痛苦，无法给他带来丝毫的功德利益，这个在僧团中其他出家人面前夸耀、炫耀自己的出家人其实是愚昧无知的人，他并没有资格成为如来的出家弟子。",-1),e("p",null,"弟子们，世间人丰厚的供养，富贵舒适的生活，世间人虔诚的尊敬、恭敬，家喻户晓的名誉声望就是这样的让人内心颤抖恐怖，就是这样的让人内心激烈搅动，就是这样的让人内心暴躁不安。",-1),e("p",null,"世间人丰厚的供养，富贵舒适的生活，世间人虔诚的尊敬、恭敬，家喻户晓的名誉声望是修行人内心达到清净安稳的障碍，是修行人内心挣脱束缚捆绑的阻碍。弟子们，因此，你们应该这样去修行：「我们要舍离、放弃已经获得的丰厚供养，我们要舍离、放弃已经获得的富贵舒适的生活，我们要舍离、放弃已经获得的世间人虔诚的尊敬、恭敬，我们要舍离、放弃已经获得的家喻户晓的名誉声望。而且我们不要执着和挂念这些已经获得的丰厚供养，不要执着和挂念这些已经获得的富贵舒适的生活，不要执着和挂念这些已经获得的世间人虔诚的尊敬、恭敬，不要执着和挂念这些已经获得的家喻户晓的名誉声望。我们不要让丰厚供养，富贵舒适的生活，世间人虔诚的尊敬、恭敬，家喻户晓的名誉声望扰乱我们的内心；不要让丰厚供养，富贵舒适的生活，世间人虔诚的尊敬、恭敬，家喻户晓的名誉声望让我们胡思乱想、内心散乱。」弟子们，你们就应该这样的去修行。”",-1),e("p",null,"佛陀说法后，听法的出家弟子们都再次的顶礼佛陀，随喜赞叹佛陀说法的无量功德，他们都按着佛陀所说的法去修行。",-1)]))}const f=t(o,[["render",_]]);export{u as __pageData,f as default};
